
class LevelScene extends Phaser.Scene {
  constructor() {
    super('LevelScene');
    this.collected = 0;
    this.totalFluffs = 1;
    this.jumpCount = 0;
    this.maxJumps = 2;
    this.jumpWasDown = false;
    this.facing = 1;
    this.finished = false;
    this.inputLocked = true;
    this.cameraY = 0;
    this.isGrounded = true;
  }

  preload() {
    // v7.2: embedded background. This prevents missing asset/path issues on GitHub Pages.
    this.load.image('paintedFluisterveldenV72', 'data:image/png;base64,');
  }

  create() {
    const s = window.FTTM.GameSettings;
    this.screenW = this.scale.width;
    this.screenH = this.scale.height;
    this.isPortrait = this.screenH >= this.screenW;

    // The embedded art plate has the same aspect ratio as landscape mobile.
    // Keep the whole painting readable instead of zooming into Amber.
    this.worldW = 1847;
    this.worldH = 851;
    this.worldZoom = Math.min(this.screenW / this.worldW, this.screenH / this.worldH);
    this.worldZoom = Phaser.Math.Clamp(this.worldZoom, 0.55, 1.05);
    this.visibleW = this.screenW / this.worldZoom;
    this.visibleH = this.screenH / this.worldZoom;

    this.physics.world.gravity.y = s.gravity || 1500;
    this.physics.world.setBounds(0, 0, this.worldW, this.worldH);
    this.cameras.main.setBounds(0, 0, this.worldW, this.worldH);
    this.cameras.main.setZoom(this.worldZoom);
    this.cameras.main.setBackgroundColor('#071632');

    if (window.FTTM.hideFinishPanel) window.FTTM.hideFinishPanel();
    if (window.FTTM.setFlowerCounter) window.FTTM.setFlowerCounter(0, this.totalFluffs);

    this.background = this.add.image(0, 0, 'paintedFluisterveldenV72')
      .setOrigin(0, 0)
      .setDisplaySize(this.worldW, this.worldH)
      .setDepth(-100);

    // The reference plate already contains an example Amber. Cover it with a soft grass patch
    // so our actual controllable Amber is the only active character.
    this.coverStaticAmber();
    this.createInvisibleGameplay();
    this.createPlayer();
    this.createCollectibles();

    this.physics.add.overlap(this.playerBody, this.fluff, this.collectMoonFluff, null, this);
    this.physics.add.overlap(this.playerBody, this.finishZone, this.tryFinish, null, this);

    this.updateCamera(true);
    this.startIntroSequence();
    this.scale.on('resize', () => { if (!this.finished) this.scene.restart(); });
  }

  coverStaticAmber() {
    // Simple prototype cover: blends static background Amber into a little flower/grass mound.
    const x = 780;
    const y = 558;
    const mound = this.add.container(x, y).setDepth(-40);
    mound.add(this.add.ellipse(0, 28, 116, 42, 0x315928, 0.82));
    mound.add(this.add.ellipse(-25, 18, 76, 34, 0x477c38, 0.92));
    mound.add(this.add.ellipse(28, 19, 80, 36, 0x3f7132, 0.9));
    for (let i = 0; i < 12; i++) {
      const px = -48 + i * 9;
      const py = 2 + Math.sin(i) * 4;
      mound.add(this.add.circle(px, py, 3.2, i % 2 ? 0xf5c9e7 : 0xf8e9a3, 0.9));
    }
  }

  createInvisibleGameplay() {
    this.finishZone = this.physics.add.staticImage(this.worldW - 210, this.terrainY(this.worldW - 210) - 90, null);
    this.finishZone.setDisplaySize(180, 220).setVisible(false).refreshBody();
  }

  createPlayer() {
    const startX = 760;
    const startY = this.terrainY(startX) - 50;

    this.playerBody = this.add.rectangle(startX, startY, 42, 88, 0xffffff, 0).setDepth(50);
    this.physics.add.existing(this.playerBody);
    this.playerBody.body.setSize(38, 82);
    this.playerBody.body.setCollideWorldBounds(true);
    this.playerBody.body.setMaxVelocity(400, 900);

    this.player = this.add.container(startX, startY).setDepth(55);
    this.shadow = this.add.ellipse(0, 49, 48, 10, 0x000000, 0.26);
    this.backFoot = this.add.ellipse(-10, 48, 16, 8, 0x563a58, 0.28);
    this.frontFoot = this.add.ellipse(10, 48, 16, 8, 0x563a58, 0.32);
    this.body = this.add.ellipse(0, 10, 42, 74, 0xff8fbd, 1);
    this.head = this.add.circle(0, -42, 31, 0xffe0b3, 1);
    this.eye = this.add.circle(12, -45, 3.5, 0x18213b, 1);
    this.hair = this.add.triangle(-9, -72, 0, 0, 55, 12, 12, 44, 0xffdc43, 1).setAngle(8);
    this.player.add([this.shadow, this.backFoot, this.frontFoot, this.body, this.head, this.eye, this.hair]);
  }

  createCollectibles() {
    const x = 1580;
    const y = this.terrainY(x) - 245;
    this.fluff = this.physics.add.staticImage(x, y, null).setVisible(false);
    this.fluff.setDisplaySize(82, 82).refreshBody();

    this.fluffVisual = this.add.container(x, y).setDepth(70);
    this.fluffVisual.add(this.add.circle(0, 0, 30, 0xfff7b6, 0.24));
    this.fluffVisual.add(this.add.circle(0, 0, 13, 0xfff2a0, 0.98));
    for (let i = 0; i < 10; i++) {
      const a = (Math.PI * 2 / 10) * i;
      this.fluffVisual.add(this.add.line(0, 0, 0, 0, Math.cos(a) * 30, Math.sin(a) * 30, 0xfff8d0, 0.9).setLineWidth(2));
    }
    this.tweens.add({ targets: this.fluffVisual, y: y - 16, duration: 1500, yoyo: true, repeat: -1, ease: 'Sine.easeInOut' });
    this.tweens.add({ targets: this.fluffVisual, angle: 8, duration: 2200, yoyo: true, repeat: -1, ease: 'Sine.easeInOut' });
  }

  startIntroSequence() {
    this.inputLocked = true;
    this.time.delayedCall(350, () => this.setMessage('Amber hoort iets buiten.', 1600));
    this.time.delayedCall(1350, () => {
      this.inputLocked = false;
      this.setMessage('De Fluistervelden voelen anders vannacht.', 2200);
    });
  }

  // Smooth invisible path over the painted artwork. This is for art-direction testing only.
  terrainY(x) {
    const pts = [
      [0, 690], [190, 670], [360, 635], [560, 600], [760, 590],
      [940, 630], [1110, 690], [1280, 715], [1460, 690],
      [1620, 620], [1770, 580], [1847, 565]
    ];
    if (x <= pts[0][0]) return pts[0][1];
    for (let i = 0; i < pts.length - 1; i++) {
      const [x1, y1] = pts[i];
      const [x2, y2] = pts[i + 1];
      if (x >= x1 && x <= x2) {
        const t = (x - x1) / (x2 - x1);
        const smooth = t * t * (3 - 2 * t);
        return Phaser.Math.Linear(y1, y2, smooth);
      }
    }
    return pts[pts.length - 1][1];
  }

  update(time, delta) {
    const dt = Math.min(delta / 1000, 0.033);
    const input = window.FTTM.InputState || {};
    if (!this.cursors) this.cursors = this.input.keyboard.createCursorKeys();
    const left = !this.inputLocked && (input.left || this.cursors.left.isDown);
    const right = !this.inputLocked && (input.right || this.cursors.right.isDown);
    const jumpDown = !this.inputLocked && (input.jump || this.cursors.up.isDown || this.cursors.space.isDown);

    const speed = window.FTTM.GameSettings.playerSpeed;
    const accel = window.FTTM.GameSettings.acceleration;
    const decel = window.FTTM.GameSettings.deceleration;

    if (left && !right) {
      this.playerBody.body.velocity.x = Phaser.Math.Clamp(this.playerBody.body.velocity.x - accel * dt, -speed, speed);
      this.facing = -1;
    } else if (right && !left) {
      this.playerBody.body.velocity.x = Phaser.Math.Clamp(this.playerBody.body.velocity.x + accel * dt, -speed, speed);
      this.facing = 1;
    } else {
      const vx = this.playerBody.body.velocity.x;
      const change = decel * dt;
      this.playerBody.body.velocity.x = Math.abs(vx) <= change ? 0 : vx - Math.sign(vx) * change;
    }

    if (jumpDown && !this.jumpWasDown && this.jumpCount < this.maxJumps) {
      this.playerBody.body.velocity.y = window.FTTM.GameSettings.jumpVelocity;
      this.jumpCount++;
      this.isGrounded = false;
    }
    if (!jumpDown && this.jumpWasDown && this.playerBody.body.velocity.y < window.FTTM.GameSettings.jumpCutVelocity) {
      this.playerBody.body.velocity.y = window.FTTM.GameSettings.jumpCutVelocity;
    }
    this.jumpWasDown = jumpDown;

    this.updateTerrainContact();
    this.updatePlayerVisual(time);
    this.updateCamera(false);
  }

  updateTerrainContact() {
    const x = this.playerBody.x;
    const groundY = this.terrainY(x) - 50;
    const body = this.playerBody.body;
    if (this.playerBody.y >= groundY && body.velocity.y >= 0) {
      // Directly anchor when grounded: no slow bobbing/floating on slopes.
      this.playerBody.y = groundY;
      body.velocity.y = 0;
      this.isGrounded = true;
      this.jumpCount = 0;
    } else {
      this.isGrounded = false;
    }
  }

  updatePlayerVisual(time) {
    this.player.x = this.playerBody.x;
    this.player.y = this.playerBody.y;
    this.player.scaleX = 1; // do not mirror the whole container; animate parts manually.

    const moving = Math.abs(this.playerBody.body.velocity.x) > 25 && this.isGrounded;
    const step = moving ? Math.sin(time / 95) : 0;
    const breathe = moving ? 0 : Math.sin(time / 850) * 0.45;

    this.body.y = 10 + breathe;
    this.head.y = -42 + breathe;
    this.eye.x = this.facing > 0 ? 12 : -12;
    this.hair.x = this.facing > 0 ? -9 : 9;
    this.hair.scaleX = this.facing;
    this.hair.angle = this.facing > 0 ? 8 : -8;
    this.frontFoot.x = this.facing * (10 + step * 4);
    this.backFoot.x = this.facing * (-10 - step * 4);
    this.frontFoot.y = 48 + Math.abs(step) * 1.2;
    this.backFoot.y = 48 + (1 - Math.abs(step)) * 1.2;
    this.body.angle = moving ? step * 1.2 : 0;
    this.head.angle = moving ? step * 0.8 : 0;
  }

  updateCamera(initial) {
    const cam = this.cameras.main;
    const targetX = Phaser.Math.Clamp(this.playerBody.x - this.visibleW * 0.43, 0, Math.max(0, this.worldW - this.visibleW));
    const targetY = Phaser.Math.Clamp(this.playerBody.y - this.visibleH * 0.62, 0, Math.max(0, this.worldH - this.visibleH));
    if (initial) {
      cam.scrollX = targetX;
      cam.scrollY = targetY;
      this.cameraY = targetY;
      return;
    }
    cam.scrollX = Phaser.Math.Linear(cam.scrollX, targetX, 0.06);
    this.cameraY = Phaser.Math.Linear(this.cameraY, targetY, 0.045);
    cam.scrollY = this.cameraY;
  }

  collectMoonFluff() {
    if (this.fluffCollected) return;
    this.fluffCollected = true;
    this.collected = 1;
    if (this.fluff) this.fluff.destroy();
    if (this.fluffVisual) this.fluffVisual.destroy();
    if (window.FTTM.setFlowerCounter) window.FTTM.setFlowerCounter(1, this.totalFluffs);
    this.setMessage('Maanpluis gevonden.', 1700);
  }

  tryFinish() {
    if (this.finished) return;
    if (this.collected < this.totalFluffs) {
      this.setMessage('Vind eerst het maanpluis.', 1500);
      return;
    }
    this.finished = true;
    this.playerBody.body.setVelocity(0, 0);
    this.inputLocked = true;
    if (window.FTTM.showFinishPanel) window.FTTM.showFinishPanel();
  }

  setMessage(text, ms) {
    if (window.FTTM.showMessage) window.FTTM.showMessage(text, ms || 2200);
  }
}

window.FTTM = window.FTTM || {};
window.FTTM.LevelScene = LevelScene;
window.LevelScene = LevelScene;
